/* Declared with gint's own font_t so the compiler lays the bitfield
 * byte, the pointers and the trailing metrics out exactly the way
 * gint's renderer reads them. */
static font_t const cms_font = {
    "Comic Sans MS",
    0, 0, 0, 0,              /* bold, italic, serif, mono */
    0,                       /* prop: fixed-width cell */
    13,                      /* line_height */
    13,                      /* data_height */
    57,                      /* block_count */
    293,                      /* glyph_count */
    0,                       /* char_spacing: advance == 10 px */
    (void *)cms_blocks,
    (void *)cms_data,
    { .width = 10, .storage_size = 5 }
};

font_t const *cms_font_get(void) { return &cms_font; }
